# "intervals=[[1,3],[1,4],[2,5],[3,5]]→3 ✓"
class _757_SetIntersectionSizeAtLeastTwo_Brute:
    def intersectionSizeTwo(self,intervals):
        intervals.sort(key=lambda x:(x[1],-x[0]))
        result=[]; 
        for l,r in intervals:
            # Count how many result elements fall in [l,r]
            cnt=sum(1 for x in result if l<=x<=r)
            if cnt==0: result+=[r-1,r]
            elif cnt==1:
                if not any(l<=x<=r for x in result[:-1]):
                    result.append(r)
                else:
                    # Find which is missing and add
                    vals=[x for x in result if l<=x<=r]
                    if vals[0]>l: result.append(l)
                    else: result.append(r)
        return len(set(result))
