1489.script:
# PHASE 1 — CLARIFY
# "Find edges that must be in every MST (critical) and those that appear in at least one MST (pseudo-critical). Right?"
# "n=5,edges=[[0,1,1],[1,2,1],[2,3,2],[0,3,2],[0,4,3],[3,4,3],[1,4,6]]→[[0,1],[2,3,4,5]] ✓"
class _1489_FindCriticalAndPseudoCriticalEdges_Brute:
    def findCriticalAndPseudoCriticalEdges(self,n,edges):
        indexed=sorted(enumerate(edges),key=lambda x:x[1][2])
        edges=[e for _,e in indexed]; orig_idx=[i for i,_ in indexed]
        def kruskal(skip=-1,force=-1):
            parent=list(range(n)); size=[1]*n; total=0; cnt=0
            def find(x):
                while parent[x]!=x: parent[x]=parent[parent[x]]; x=parent[x]
                return x
            def union(x,y):
                px,py=find(x),find(y)
                if px==py: return False
                if size[px]<size[py]: px,py=py,px
                parent[py]=px; size[px]+=size[py]; return True
            if force>=0:
                u,v,w=edges[force]; union(u,v); total+=w; cnt+=1
            for i,(u,v,w) in enumerate(edges):
                if i==skip or i==force: continue
                if union(u,v): total+=w; cnt+=1
            return total if cnt==n-1 else float('inf')
        base=kruskal()
        critical=[]; pseudo=[]
        for i in range(len(edges)):
            if kruskal(skip=i)>base: critical.append(orig_idx[i])
            elif kruskal(force=i)==base: pseudo.append(orig_idx[i])
        return [critical,pseudo]
class _1489_FindCriticalAndPseudoCriticalEdges:
    def findCriticalAndPseudoCriticalEdges(self,n,edges):
        # Same approach — already optimal for this problem
        return self.findCriticalAndPseudoCriticalEdges.__wrapped__(n,edges)
# For each edge: skip it (if MST cost increases → critical); force it (if MST cost unchanged → pseudo). O(E² α(V)).
# Follow-up: if only critical edges needed — Matroid intersection approach O(E² log E).
# Follow-up: dynamic MST updates — link-cut trees for O(log n) per edge insertion/deletion.

