                        dist[nr][nc]=dist[r][c]+nc_
                        if nc_==0: dq.appendleft((dist[nr][nc],nr,nc))
                        else: dq.append((dist[nr][nc],nr,nc))
        return dist[m-1][n-1]
class _1368_MinCostValidPathInGrid:
