        from collections import deque
        m,n=len(grid),len(grid[0])
        DIRS=[(0,1),(0,-1),(1,0),(-1,0)]
        dist=[[float('inf')]*n for _ in range(m)]; dist[0][0]=0
        dq=deque([(0,0,0)])
        while dq:
            cost,r,c=dq.popleft()
            if cost>dist[r][c]: continue
            for d,(dr,dc) in enumerate(DIRS,1):
