# PHASE 1 — CLARIFY
# "Find minimum weight subgraph where src1 and src2 can both reach dest. Right?"
# "n=6,edges=[[0,2,2],[0,5,6],[1,0,3],[1,4,5],[2,1,1],[2,3,3],[2,3,4],[3,4,2],[4,5,1]],src1=0,src2=1,dest=5→9 ✓"
class _2203_MinWeightedSubgraphRequiredPaths_Brute:
    def minimumWeight(self,n,edges,src1,src2,dest):
        import heapq
        from collections import defaultdict
        g=defaultdict(list); gr=defaultdict(list)
        for u,v,w in edges: g[u].append((v,w)); gr[v].append((u,w))
        def dijkstra(src,graph):
            dist=[float('inf')]*n; dist[src]=0; heap=[(0,src)]
            while heap:
                d,u=heapq.heappop(heap)
                if d>dist[u]: continue
                for v,w in graph[u]:
                    if dist[u]+w<dist[v]: dist[v]=dist[u]+w; heapq.heappush(heap,(dist[v],v))
            return dist
        d1=dijkstra(src1,g); d2=dijkstra(src2,g); dd=dijkstra(dest,gr)
        best=min(d1[i]+d2[i]+dd[i] for i in range(n))
        return best if best<float('inf') else -1
class _2203_MinWeightedSubgraphRequiredPaths:
    def minimumWeight(self,n,edges,src1,src2,dest):
        import heapq
        from collections import defaultdict
        fwd=defaultdict(list); rev=defaultdict(list)
        for u,v,w in edges: fwd[u].append((v,w)); rev[v].append((u,w))
        def dijk(src,g):
            dist=[float('inf')]*n; dist[src]=0; h=[(0,src)]
            while h:
                d,u=heapq.heappop(h)
                if d>dist[u]: continue
                for v,w in g[u]:
                    if d+w<dist[v]: dist[v]=d+w; heapq.heappush(h,(dist[v],v))
            return dist
        d1=dijk(src1,fwd); d2=dijk(src2,fwd); dd=dijk(dest,rev)
        ans=min(a+b+c for a,b,c in zip(d1,d2,dd))
        return -1 if ans==float('inf') else ans
