# PHASE 1 — CLARIFY
# "Distribute n cookie bags among k children to minimize the maximum sum any child receives. Right?"
# "cookies=[8,15,10,20,8],k=2→31 ✓"
class _2305_FairDistributionOfCookies_Brute:
    def distributeCookies(self,cookies,k):
        result=[float('inf')]
        def bt(idx,children):
            if idx==len(cookies): result[0]=min(result[0],max(children)); return
            for i in range(k):
                children[i]+=cookies[idx]
                bt(idx+1,children)
                children[i]-=cookies[idx]
                if children[i]==0: break  # prune symmetric branches
        bt(0,[0]*k); return result[0]
class _2305_FairDistributionOfCookies:
    def distributeCookies(self,cookies,k):
        n=len(cookies); subset_sum=[0]*(1<<n)
        for mask in range(1<<n):
            for i in range(n):
                if mask>>i&1: subset_sum[mask]+=cookies[i]
        dp=[[float('inf')]*(1<<n) for _ in range(k+1)]
        dp[0][0]=0
        for j in range(1,k+1):
            for mask in range(1<<n):
                sub=mask
                while sub:
                    dp[j][mask]=min(dp[j][mask],max(dp[j-1][mask^sub],subset_sum[sub]))
                    sub=(sub-1)&mask
        return dp[k][(1<<n)-1]
